from dataclasses import dataclass

@dataclass(frozen=True)
class User:
    user_id: str
    active: bool

def active_ids(users: list[User]) -> list[str]:
    return [user.user_id for user in users if user.active]

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parsePort(value: string): Result<number> {
  const port = Number(value);
  return Number.isInteger(port) && port > 0 && port < 65536
    ? { ok: true, value: port }
    : { ok: false, error: "invalid port" };
}

export async function retry(operation, attempts = 3) {
  let lastError;
  for (let index = 0; index < attempts; index += 1) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Task {
    id: String,
    done: bool,
}

fn pending_ids(tasks: &[Task]) -> Vec<&str> {
    tasks.iter().filter(|task| !task.done).map(|task| task.id.as_str()).collect()
}

