import "errors"

func Pop(items []string) (string, []string, error) {
	if len(items) == 0 {
		return "", items, errors.New("empty queue")
	}
	return items[0], items[1:], nil
}

import java.util.List;

public final class Example {
    public static long positiveTotal(List<Integer> values) {
        return values.stream()
                .filter(value -> value > 0)
                .mapToLong(Integer::longValue)
                .sum();
    }
}

#include <stddef.h>

size_t count_nonzero(const int *values, size_t length) {
    size_t count = 0;
    for (size_t i = 0; i < length; ++i) {
        if (values[i] != 0) {
            ++count;
        }
    }
    return count;
}

#include <optional>
#include <string>

std::optional<int> parse_count(const std::string& text) {
    try {
        int value = std::stoi(text);
        return value >= 0 ? std::optional<int>{value} : std::nullopt;
    } catch (...) {
        return std::nullopt;
    }
}
